-- Attributed historic, read-only match snapshot; never insert as published club results.
begin;
create table if not exists public.external_sourced_match_archive (
 id uuid primary key default gen_random_uuid(),
 team_code text not null references public.club_teams(code) on delete restrict,
 season text not null check (season ~ '^20[0-9]{2}-20[0-9]{2}$'),
 match_date date not null,
 opponent_name text not null check (length(btrim(opponent_name)) between 2 and 120),
 competition text not null check (length(btrim(competition)) between 3 and 100),
 is_home boolean not null,
 home_score smallint not null check (home_score between 0 and 99),
 away_score smallint not null check (away_score between 0 and 99),
 source_url text not null check (source_url like 'https://%' and length(source_url)<=500),
 reviewed_on date not null default date '2026-10-22',
 club_validated boolean not null default false check (club_validated=false),
 unique(team_code,season,match_date,opponent_name,competition)
);
create index if not exists external_archive_season_idx
 on public.external_sourced_match_archive(season,team_code,match_date desc);
alter table public.external_sourced_match_archive enable row level security;
revoke all on public.external_sourced_match_archive from public,anon,authenticated;
grant select on public.external_sourced_match_archive to anon,authenticated;
drop policy if exists external_sourced_match_archive_read on public.external_sourced_match_archive;
create policy external_sourced_match_archive_read
 on public.external_sourced_match_archive for select to anon,authenticated using(true);
